    })

    it('applies reviver to `message.state` on JUMP_TO_STATE', async () => {
      const initialState = { count: 0 }
      const api = createStore(
        devtools(() => initialState, { enabled: true, serialize: { reviver } }),
      )
      const newState = { count: 5 }

